/**
 * @class CXOrderManager
 * @brief 샌드박스 세션 내의 주문 실행 및 관리 담당
 */
class CXOrderManager {
private:
    ulong           m_ticket;
    string          m_sid;
    CTrade          m_trade;
    ICXContext*     m_ctx;

public:
    CXOrderManager(ICXContext* ctx) : m_ctx(ctx), m_ticket(0), m_sid("") {}
    ~CXOrderManager() {}

    void SetMagic(ulong magic) { m_trade.SetExpertMagicNumber(magic); }
/**
 * @brief 진입 주문 실행 (xa_entry 기반)
 */
void ExecuteEntry(ICXParam* xp) {
    if(IS_NULL(m_ctx) || IS_NULL(xp)) return;

    CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
    if(IS_INVALID(sig)) return;

    //--- [Point 4] 중앙 집중형 검증 가드 (CXGuard) 적용
    IXGuard* guard = CX_GET_OBJ(m_ctx, "guard", IXGuard);
    if(IS_VALID(guard)) {
        if(!guard.ValidateMagic(sig.cno) || 
           !guard.ValidateSID(sig.sid) || 
           !guard.ValidateLot(sig.symbol, sig.lot) ||
           !guard.ValidatePrice(sig.symbol, sig.price_signal)) {

            string err = "[GUARD-BLOCK] " + guard.GetLastError();
            XP_LOG_ERROR(xp, err);
            sig.xe_status = XE_ERROR;
            sig.xe_status_msg = err;
            return;
        }
    }

    m_sid = sig.sid;
...
        XP_LOG_INFO(xp, StringFormat("[EXEC-ENTRY] SID:%s, Dir:%d, Type:%d, Lot:%.2f, Price:%.5f", 
                   m_sid, sig.dir, sig.type, sig.lot, sig.price_signal));

        //--- 주문 타입 및 방향 결정 (DIP/Unified)
        ENUM_ORDER_TYPE order_type;
        if(sig.type == ORDER_MARKET) {
            order_type = (sig.dir == CX_DIR_BUY) ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
        } else {
            order_type = (sig.dir == CX_DIR_BUY) ? ORDER_TYPE_BUY_LIMIT : ORDER_TYPE_SELL_LIMIT;
        }

        //--- 단일 OrderSend로 통합 실행 (if-else 최소화)
        double price = (sig.type == ORDER_MARKET) ? 0 : sig.price_signal;
        bool res = m_trade.OrderOpen(sig.symbol, order_type, sig.lot, 0, price, sig.sl, sig.tp, ORDER_TIME_GTC, 0, m_sid);

        if(!res) {
            XP_LOG_ERROR(xp, StringFormat("[EXEC-FAIL] RetCode:%d, Msg:%s", m_trade.ResultRetcode(), m_trade.ResultRetcodeDescription()));
            sig.xe_status = XE_ERROR;
            sig.xe_status_msg = "Execution Failed: " + m_trade.ResultRetcodeDescription();
        }
        else {
            m_ticket = m_trade.ResultOrder();
            sig.ticket = (long)m_ticket;

            sig.xe_status = (sig.type == ORDER_MARKET) ? XE_EXECUTED : XE_PENDING_PLACED;
            sig.xe_status_msg = (sig.type == ORDER_MARKET) ? "[EXEC] Market Entry Success" 
                                                           : StringFormat("[PENDING] Limit Order Placed (Tkt:%lld)", m_ticket);

            XP_LOG_OK(xp, sig.xe_status_msg);
        }
    }

    /**
     * @brief 주문 수정 (진트레)
     */
    bool ModifyOrder(ulong ticket, double price, double sl, double tp) {
        if(ticket == 0) return false;
        return m_trade.OrderModify(ticket, price, sl, tp, ORDER_TIME_GTC, 0);
