/**
 * @class CXTradingSession
 * @brief 독립적인 샌드박스 실행 단위
 */
class CXTradingSession : public CObject {
private:
    ICXContext*         m_ctx;
    IRepository*        m_repo;
    CXLogDispatcher*    m_logger;
    ICXFluentSequence*  m_sequence;
    ICXContext*         m_globalCtx;
    bool                m_isActive;

    //-- Managers (Managed via Context)
    CXEntryManager*    m_entryMgr;
    CXOrderManager*    m_orderMgr;
    CXPositionManager* m_posMgr;
    CXExitManager*     m_exitMgr;

public:
    CXTradingSession(IRepository* repo, ICXContext* globalCtx) 
        : m_repo(repo), m_globalCtx(globalCtx), m_isActive(false) {
        Bootstrap();
    }

    ~CXTradingSession() {
        SAFE_DELETE(m_entryMgr); SAFE_DELETE(m_orderMgr);
        SAFE_DELETE(m_posMgr);   SAFE_DELETE(m_exitMgr);
        SAFE_DELETE(m_sequence); SAFE_DELETE(m_logger);
        SAFE_DELETE(m_ctx);
    }

    /**
     * @brief 통합 이벤트 수신 및 시퀀스 구동
     */
    void Pulse(ICXParam* xp) {
        if(!m_isActive && xp.GetInt() != 100) return; // 100: EVENT_START
        if(IS_VALID(m_sequence)) m_sequence.Pulse(xp);
    }

    void Start(ICXParam* xp) {
        m_isActive = true;
        InitLogger(xp.GetString());
        Pulse(xp.SetInt(100)); // Start 이벤트
    }

    void InjectState(CXSignal* sig) {
        m_isActive = true;
        CXParam xp;
        xp.SetSignal(sig);
        Pulse(xp.SetInt(101)); // 복구(Injection) 이벤트
    }

    void Reset() {
        m_isActive = false;
        if(IS_VALID(m_sequence)) m_sequence.ForceState(SESSION_READY);
    }

    bool IsActive() const { return m_isActive; }

private:
    void Bootstrap() {
        m_ctx = new CXContext();
        m_logger = new CXLogDispatcher();
        if(IS_INVALID(m_ctx) || IS_INVALID(m_logger)) return;

        // 글로벌 서비스 상속 (Guard, Config 등)
        if(IS_VALID(m_globalCtx)) {
            m_ctx.Register("guard", m_globalCtx.Get("guard"));
            m_ctx.Register("config", m_globalCtx.Get("config"));
        }

        m_ctx.Set("repo", m_repo);
        m_ctx.Set("logger", m_logger);

        m_entryMgr = new CXEntryManager(m_ctx);
        m_orderMgr = new CXOrderManager(m_ctx);
        m_posMgr   = new CXPositionManager(m_ctx);
        m_exitMgr  = new CXExitManager(m_ctx);

        if(IS_INVALID(m_entryMgr) || IS_INVALID(m_orderMgr) || IS_INVALID(m_posMgr) || IS_INVALID(m_exitMgr)) return;

        m_ctx.Set("entry_mgr", m_entryMgr); m_ctx.Set("order_mgr", m_orderMgr);
        m_ctx.Set("pos_mgr", m_posMgr);     m_ctx.Set("exit_mgr", m_exitMgr);

        m_sequence = new CXFluentSequence(m_ctx, "SessionSeq");
        InitSequence();
    }

    void InitLogger(string sid) {
        CXFileLogger* fileLog = new CXFileLogger();
        if(IS_VALID(fileLog) && fileLog.Init(sid)) {
            m_logger.SetFileLogger(fileLog);
        }
        m_logger.Log(LOG_LVL_OK, ">>> Session Initialized <<<");
    }

    void InitSequence() {
        CXFluentSequence* seq = dynamic_cast<CXFluentSequence*>(m_sequence);
        if(IS_INVALID(seq)) return;

        //-- 1. 진입 파이프라인
        seq.From(SESSION_READY).Execute(new CXStepEntry()).OnSuccess(STATE_ENTRY_TRAILING);
        seq.From(STATE_ENTRY_TRAILING).Execute(new CXStepEntryTrailing()).OnSuccess(SESSION_ACTIVE);

        //-- 2. 활성 파이프라인 (Monitor)
        seq.From(SESSION_ACTIVE).Execute(new CXStepMonitor()).Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING);

        //-- 3. 청산 파이프라인 (3-Layer Guard - Atomized)
        seq.From(SESSION_LIQUIDATING).Execute(new CXStepExitTicket()).OnSuccess(STATE_EXIT_SWEEP);
        seq.From(STATE_EXIT_SWEEP).Execute(new CXStepExitSweep()).OnSuccess(STATE_EXIT_VERIFY);
        seq.From(STATE_EXIT_VERIFY).Execute(new CXStepExitVerify())
           .OnSuccess(SESSION_CLOSED)
           .OnFail(SESSION_LIQUIDATING) // 실패 시 L1부터 다시 시도
           .Retries(5);                 

        seq.Build();
    }
};

